insert into booking (booking_id, patron_id, perf_id, seats, paid, rating)
select row_number() over (order by b.n), b.p + 1, f.perf_id, b.seats,
       round(f.price * b.seats * case when b.n % 7 = 0 then 0.80 else 1 end, 2),
       case when (b.n * 7 + b.m) % 4 = 0 then null
            else greatest(1, least(5, round(case pr.genre when 'drama' then 3.6 when 'comedy' then 4.1 when 'musical' then 4 when 'opera' then 3.5 when 'dance' then 3.7 when 'tragedy' then 3.3 when 'revue' then 3.8 end + ((b.n * 7919 + b.p * 104729) % 21 - 10) / 4.0))) end
from (select n, p, m, case when x < 2 then 1 when x < 7 then 2 when x < 8 then 3 when x < 10 then 4 when x < 11 then 6 else 8 end as seats
      from (select n, n % 6000 as p, n / 6000 as m, (n * 13 + n / 6000) % 12 as x from generate_series(0, 77999) n) g
      where m < 1 + (p * 7) % 13 or (p % 9 = 0 and m < 13)
      order by n limit 45000) b
join performance f on f.perf_id = 1 + (b.p * 7919 + b.m * 173) % 2400
join production pr on pr.prod_id = f.prod_id;

